BEGIN;
SET LOCAL app.is_platform = 'on';
CREATE TEMP TABLE r ON COMMIT DROP AS SELECT id FROM restaurants WHERE name ILIKE '%chupacabra%';
DO $$ BEGIN IF (SELECT count(*) FROM r) <> 1 THEN RAISE EXCEPTION 'Se esperaba 1 restaurante Chupacabras, hay %', (SELECT count(*) FROM r); END IF;
IF EXISTS (SELECT 1 FROM menu_items WHERE restaurant_id=(SELECT id FROM r) AND name IN ('Sencilla','Cruji Pollo','Papas Fritas','Soda')) OR EXISTS (SELECT 1 FROM modifier_groups WHERE restaurant_id=(SELECT id FROM r) AND name='Ingredientes') THEN RAISE EXCEPTION 'El menu ya estaba cargado; no se carga nada'; END IF; END $$;
CREATE TEMP TABLE g (k text, id uuid) ON COMMIT DROP;
WITH x AS (INSERT INTO modifier_groups (restaurant_id,name,min_selections,max_selections,sort_order) SELECT id,'Ingredientes',0,NULL,0 FROM r RETURNING id) INSERT INTO g SELECT 'sin', id FROM x;
